const storeMenu=document.querySelector('#storeMenu'),storeDrawer=document.querySelector('#storeDrawer'),storeClose=document.querySelector('#storeClose');if(storeMenu&&storeDrawer&&storeClose){const closeStoreMenu=()=>{storeDrawer.hidden=true;storeMenu.setAttribute('aria-expanded','false')};storeMenu.addEventListener('click',()=>{storeDrawer.hidden=false;storeMenu.setAttribute('aria-expanded','true')});storeClose.addEventListener('click',closeStoreMenu);storeDrawer.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeStoreMenu))}
